INSERT INTO shj_creature_translations(creature_id,locale,name,aliases,summary,detail,status) VALUES
('25000000-0000-4000-8000-000000000001','zh-CN','羬羊',ARRAY[]::text[],'兽，见于钱来之山（第 1 段）。','原文：有獸焉，其狀如羊而馬尾，名曰羬羊，其脂可以已腊。','draft'),
('25000000-0000-4000-8000-000000000001','en','Qianyang',ARRAY['羬羊'],'','','draft'),
('25000000-0000-4000-8000-000000000002','zh-CN','䳋渠',ARRAY[]::text[],'鸟，见于松果之山（第 2 段）。','原文：有鳥焉，其名曰䳋渠，其狀如山雞，黑身赤足，可以已𦢊。','draft'),
('25000000-0000-4000-8000-000000000002','en','Tiaoqu',ARRAY['䳋渠'],'','','draft'),
('25000000-0000-4000-8000-000000000003','zh-CN','肥𧔥',ARRAY[]::text[],'蛇，见于太华之山（第 3 段）。','原文：有蛇焉，名曰肥𧔥，六足四翼，見則天下大旱。','draft'),
('25000000-0000-4000-8000-000000000003','en','Feiyi',ARRAY['肥𧔥'],'','','draft'),
('25000000-0000-4000-8000-000000000004','zh-CN','葱聋',ARRAY['葱聾'],'兽，见于符禺之山（第 5 段）。','原文：其獸多葱聾，其狀如羊而赤鬣。','draft'),
('25000000-0000-4000-8000-000000000004','en','Conglong',ARRAY['葱聾'],'','','draft'),
('25000000-0000-4000-8000-000000000005','zh-CN','鴖',ARRAY[]::text[],'鸟，见于符禺之山（第 5 段）。','原文：其鳥多鴖，其狀如翠而赤喙，可以禦火。','draft'),
('25000000-0000-4000-8000-000000000005','en','Min',ARRAY['鴖'],'','','draft'),
('25000000-0000-4000-8000-000000000006','zh-CN','䰷鱼',ARRAY['䰷魚'],'鱼，见于英山（第 7 段）。','原文：其中多䰷魚，其狀如鱉，其音如羊。','draft'),
('25000000-0000-4000-8000-000000000006','en','Fuyu',ARRAY['䰷魚'],'','','draft'),
('25000000-0000-4000-8000-000000000007','zh-CN','肥遗',ARRAY['肥遺'],'鸟，见于英山（第 7 段）。','原文：有鳥焉，其狀如鶉，黃身而赤喙，其名曰肥遺，食之已癘，可以殺蟲。','draft'),
('25000000-0000-4000-8000-000000000007','en','Feiyi',ARRAY['肥遺'],'','','draft'),
('25000000-0000-4000-8000-000000000008','zh-CN','人鱼',ARRAY['人魚'],'鱼，见于竹山（第 8 段）。','原文：其中多水玉，多人魚。','draft'),
('25000000-0000-4000-8000-000000000008','en','Renyu',ARRAY['人魚'],'','','draft'),
('25000000-0000-4000-8000-000000000009','zh-CN','毫彘',ARRAY[]::text[],'兽，见于竹山（第 8 段）。','原文：有獸焉，其狀如豚而白毛，大如笄而黑端，名曰毫彘。','draft'),
('25000000-0000-4000-8000-000000000009','en','Haozhi',ARRAY['毫彘'],'','','draft'),
('25000000-0000-4000-8000-000000000010','zh-CN','嚣',ARRAY['囂'],'兽，见于羭次之山（第 10 段）。','原文：有獸焉，其狀如禺而長臂，善投，其名曰囂。','draft'),
('25000000-0000-4000-8000-000000000010','en','Xiao',ARRAY['囂'],'','','draft'),
('25000000-0000-4000-8000-000000000011','zh-CN','橐𩇯',ARRAY[]::text[],'鸟，见于羭次之山（第 10 段）。','原文：有鳥焉，其狀如梟，人面而一足，曰橐𩇯，冬見夏蟄，服之不畏雷。','draft'),
('25000000-0000-4000-8000-000000000011','en','Tuofei',ARRAY['橐𩇯'],'','','draft'),
('25000000-0000-4000-8000-000000000012','zh-CN','谿边',ARRAY['谿邊'],'兽，见于天帝之山（第 15 段）。','原文：有獸焉，其狀如狗，名曰谿邊，席其皮者不蠱。','draft'),
('25000000-0000-4000-8000-000000000012','en','Xibian',ARRAY['谿邊'],'','','draft'),
('25000000-0000-4000-8000-000000000013','zh-CN','栎',ARRAY['櫟'],'鸟，见于天帝之山（第 15 段）。','原文：有鳥焉，其狀如鶉，黑文而赤翁，名曰櫟，食之已痔。','draft'),
('25000000-0000-4000-8000-000000000013','en','Li',ARRAY['櫟'],'','','draft'),
('25000000-0000-4000-8000-000000000014','zh-CN','𤣎如',ARRAY[]::text[],'兽，见于皋涂之山（第 16 段）。','原文：有獸焉，其狀如鹿而白尾，馬足人手而四角，名曰𤣎如。','draft'),
('25000000-0000-4000-8000-000000000014','en','Leiru',ARRAY['𤣎如'],'','','draft'),
('25000000-0000-4000-8000-000000000015','zh-CN','数斯',ARRAY['數斯'],'鸟，见于皋涂之山（第 16 段）。','原文：有鳥焉，其狀如鴟而人足，名曰數斯，食之已癭。','draft'),
('25000000-0000-4000-8000-000000000015','en','Shusi',ARRAY['數斯'],'','','draft'),
('25000000-0000-4000-8000-000000000016','zh-CN','𤛎',ARRAY[]::text[],'兽，见于黄山（第 17 段）。','原文：有獸焉，其狀如牛，而蒼黑大目，其名曰𤛎。','draft'),
('25000000-0000-4000-8000-000000000016','en','Min',ARRAY['𤛎'],'','','draft'),
('25000000-0000-4000-8000-000000000017','zh-CN','鹦鹉',ARRAY['鸚䳇'],'鸟，见于黄山（第 17 段）。','原文：有鳥焉，其狀如鴞，青羽赤喙，人舌能言，名曰鸚䳇。','draft'),
('25000000-0000-4000-8000-000000000017','en','Yingwu',ARRAY['鸚䳇'],'','','draft'),
('25000000-0000-4000-8000-000000000018','zh-CN','鸓',ARRAY[]::text[],'鸟，见于翠山（第 18 段）。','原文：其鳥多鸓，其狀如鵲，赤黑而兩首四足，可以禦火。','draft'),
('25000000-0000-4000-8000-000000000018','en','Lei',ARRAY['鸓'],'','','draft'),
('25000000-0000-4000-8000-000000000019','zh-CN','鸾鸟',ARRAY['鸞鳥'],'鸟，见于女床之山（第 25 段）。','原文：有鳥焉，其狀如翟而五彩文，名曰鸞鳥，見則天下安寧。','draft'),
('25000000-0000-4000-8000-000000000019','en','Luanniao',ARRAY['鸞鳥'],'','','draft'),
('25000000-0000-4000-8000-000000000020','zh-CN','凫徯',ARRAY['鳧徯'],'鸟，见于鹿台之山（第 27 段）。','原文：有鳥焉，其狀如雄雞而人面，名曰鳧徯，其鳴自叫也，見則有兵。','draft'),
('25000000-0000-4000-8000-000000000020','en','Fuxi',ARRAY['鳧徯'],'','','draft'),
('25000000-0000-4000-8000-000000000021','zh-CN','朱厌',ARRAY['朱厭'],'兽，见于小次之山（第 29 段）。','原文：有獸焉，其狀如猿，而白首赤足，名曰朱厭，見則大兵。','draft'),
('25000000-0000-4000-8000-000000000021','en','Zhuyan',ARRAY['朱厭'],'','','draft'),
('25000000-0000-4000-8000-000000000022','zh-CN','罗罗',ARRAY['羅羅'],'鸟，见于莱山（第 37 段）。','原文：其鳥多羅羅，是食人。','draft'),
('25000000-0000-4000-8000-000000000022','en','Luoluo',ARRAY['羅羅'],'','','draft'),
('25000000-0000-4000-8000-000000000023','zh-CN','举父',ARRAY['舉父'],'兽，见于崇吾之山（第 39 段）。','原文：有獸焉，其狀如禺而文臂，豹虎而善投，名曰舉父。','draft'),
('25000000-0000-4000-8000-000000000023','en','Jufu',ARRAY['舉父'],'','','draft'),
('25000000-0000-4000-8000-000000000024','zh-CN','蛮蛮',ARRAY['蠻蠻'],'鸟，见于崇吾之山（第 39 段）。','原文：有鳥焉，其狀如鳧，而一翼一目，相得乃飛，名曰蠻蠻，見則天下大水。','draft'),
('25000000-0000-4000-8000-000000000024','en','Manman',ARRAY['蠻蠻'],'','','draft'),
('25000000-0000-4000-8000-000000000025','zh-CN','鼓',ARRAY[]::text[],'神，见于钟山（第 43 段）。','原文：其子曰鼓，其狀如人面而龍身，是與欽䲹殺葆江于崑崙之陽','draft'),
('25000000-0000-4000-8000-000000000025','en','Gu',ARRAY['鼓'],'','','draft'),
('25000000-0000-4000-8000-000000000026','zh-CN','钦䲹',ARRAY['欽䲹'],'神，见于钟山（第 43 段）。','原文：欽䲹化為大鶚，其狀如鵰而黑文白首，赤喙而虎爪，其音如晨鵠，見則有大兵','draft'),
('25000000-0000-4000-8000-000000000026','en','Qinpi',ARRAY['欽䲹'],'','','draft'),
('25000000-0000-4000-8000-000000000027','zh-CN','文鳐鱼',ARRAY['文鰩魚'],'鱼，见于泰器之山（第 44 段）。','原文：是多文鰩魚，狀如鯉魚，魚身而鳥翼，蒼文而白首，赤喙，常行西海，遊於東海，以夜飛。','draft'),
('25000000-0000-4000-8000-000000000027','en','Wenyaoyu',ARRAY['文鰩魚'],'','','draft'),
('25000000-0000-4000-8000-000000000028','zh-CN','蠃母',ARRAY[]::text[],'未定，见于槐江之山（第 45 段）。','原文：其中多蠃母，其上多青雄黃','draft'),
('25000000-0000-4000-8000-000000000028','en','Luomu',ARRAY['蠃母'],'','','draft'),
('25000000-0000-4000-8000-000000000029','zh-CN','英招',ARRAY[]::text[],'神，见于槐江之山（第 45 段）。','原文：神英招司之，其狀馬身而人面，虎文而鳥翼，徇于四海，其音如榴。','draft'),
('25000000-0000-4000-8000-000000000029','en','Yingzhao',ARRAY['英招'],'','','draft'),
('25000000-0000-4000-8000-000000000030','zh-CN','天神',ARRAY[]::text[],'神，见于槐江之山（第 45 段）。','原文：有天神焉，其狀如牛，而八足二首馬尾，其音如勃皇，見則其邑有兵。','draft'),
('25000000-0000-4000-8000-000000000030','en','Tianshen',ARRAY['天神'],'','','draft'),
('25000000-0000-4000-8000-000000000031','zh-CN','陆吾',ARRAY['陸吾'],'神，见于昆仑之丘（第 46 段）。','原文：神陸吾司之。其神狀虎身而九尾，人面而虎爪；是神也，司天之九部及帝之囿時。','draft'),
('25000000-0000-4000-8000-000000000031','en','Luwu',ARRAY['陸吾'],'','','draft'),
('25000000-0000-4000-8000-000000000032','zh-CN','土蝼',ARRAY['土螻'],'兽，见于昆仑之丘（第 46 段）。','原文：有獸焉，其狀如羊而四角，名曰土螻，是食人。','draft'),
('25000000-0000-4000-8000-000000000032','en','Tulou',ARRAY['土螻'],'','','draft'),
('25000000-0000-4000-8000-000000000033','zh-CN','钦原',ARRAY['欽原'],'鸟，见于昆仑之丘（第 46 段）。','原文：有鳥焉，其狀如蜂，大如鴛鴦，名曰欽原，蠚鳥獸則死，蠚木則枯。','draft'),
('25000000-0000-4000-8000-000000000033','en','Qinyuan',ARRAY['欽原'],'','','draft'),
('25000000-0000-4000-8000-000000000034','zh-CN','鹑鸟',ARRAY['鶉鳥'],'鸟，见于昆仑之丘（第 46 段）。','原文：有鳥焉，其名曰鶉鳥，是司帝之百服。','draft'),
('25000000-0000-4000-8000-000000000034','en','Chunniao',ARRAY['鶉鳥'],'','','draft'),
('25000000-0000-4000-8000-000000000035','zh-CN','滑鱼',ARRAY['滑魚'],'鱼，见于乐游之山（第 47 段）。','原文：其中多滑魚，其狀如蛇而四足，是食魚。','draft'),
('25000000-0000-4000-8000-000000000035','en','Huayu',ARRAY['滑魚'],'','','draft'),
('25000000-0000-4000-8000-000000000036','zh-CN','长乘',ARRAY['長乘'],'神，见于蠃母之山（第 48 段）。','原文：神長乘司之，是天之九德也。其神狀如人而犳尾。','draft'),
('25000000-0000-4000-8000-000000000036','en','Changcheng',ARRAY['長乘'],'','','draft'),
('25000000-0000-4000-8000-000000000037','zh-CN','西王母',ARRAY[]::text[],'神，见于玉山（第 49 段）。','原文：西王母其狀如人，豹尾虎齒而善嘯，蓬髮戴勝，是司天之厲及五殘。','draft'),
('25000000-0000-4000-8000-000000000037','en','Xiwangmu',ARRAY['西王母'],'','','draft'),
('25000000-0000-4000-8000-000000000038','zh-CN','狡',ARRAY[]::text[],'兽，见于玉山（第 49 段）。','原文：有獸焉，其狀如犬而豹文，其角如牛，其名曰狡，其音如吠犬，見則其國大穰。','draft'),
('25000000-0000-4000-8000-000000000038','en','Jiao',ARRAY['狡'],'','','draft'),
('25000000-0000-4000-8000-000000000039','zh-CN','胜遇',ARRAY[]::text[],'鸟，见于玉山（第 49 段）。','原文：有鳥焉，其狀如翟而赤，名曰胜遇，是食魚，其音如錄，見則其國大水。','draft'),
('25000000-0000-4000-8000-000000000039','en','Shengyu',ARRAY['胜遇'],'','','draft'),
('25000000-0000-4000-8000-000000000040','zh-CN','白帝少昊',ARRAY[]::text[],'神，见于长留之山（第 52 段）。','原文：其神白帝少昊居之。','draft'),
('25000000-0000-4000-8000-000000000040','en','Baidishaohao',ARRAY['白帝少昊'],'','','draft'),
('25000000-0000-4000-8000-000000000041','zh-CN','狰',ARRAY['猙'],'兽，见于章莪之山（第 53 段）。','原文：有獸焉，其狀如赤豹，五尾一角，其音如擊石，其名如猙。','draft'),
('25000000-0000-4000-8000-000000000041','en','Zheng',ARRAY['猙'],'','','draft'),
('25000000-0000-4000-8000-000000000042','zh-CN','毕方',ARRAY['畢方'],'鸟，见于章莪之山（第 53 段）。','原文：有鳥焉，其狀如鶴，一足，赤文青質而白喙，名曰畢方，其鳴自叫也，見則其邑有譌火。','draft'),
('25000000-0000-4000-8000-000000000042','en','Bifang',ARRAY['畢方'],'','','draft'),
('25000000-0000-4000-8000-000000000043','zh-CN','天狗',ARRAY[]::text[],'兽，见于阴山（第 54 段）。','原文：有獸焉，其狀如狸而白首，名曰天狗，其音如榴榴，可以禦凶。','draft'),
('25000000-0000-4000-8000-000000000043','en','Tiangou',ARRAY['天狗'],'','','draft'),
('25000000-0000-4000-8000-000000000044','zh-CN','三青鸟',ARRAY['三青鳥'],'鸟，见于三危之山（第 56 段）。','原文：三青鳥居之。','draft'),
('25000000-0000-4000-8000-000000000044','en','Sanqingniao',ARRAY['三青鳥'],'','','draft'),
('25000000-0000-4000-8000-000000000045','zh-CN','𢕟𢓨',ARRAY[]::text[],'兽，见于三危之山（第 56 段）。','原文：其上有獸焉，其狀如牛，白身四角，其毫如披蓑，其名曰𢕟𢓨，是食人。','draft'),
('25000000-0000-4000-8000-000000000045','en','Aoyin',ARRAY['𢕟𢓨'],'','','draft'),
('25000000-0000-4000-8000-000000000046','zh-CN','鸱',ARRAY['鴟'],'鸟，见于三危之山（第 56 段）。','原文：有鳥焉，一首而三身，其狀如𪇱，其名曰鴟。','draft'),
('25000000-0000-4000-8000-000000000046','en','Chi',ARRAY['鴟'],'','','draft'),
('25000000-0000-4000-8000-000000000047','zh-CN','耆童',ARRAY[]::text[],'神，见于騩山（第 57 段）。','原文：神耆童居之，其音常如鍾磬。','draft'),
('25000000-0000-4000-8000-000000000047','en','Qitong',ARRAY['耆童'],'','','draft'),
('25000000-0000-4000-8000-000000000048','zh-CN','帝江',ARRAY[]::text[],'神，见于天山（第 58 段）。','原文：有神焉，其狀如黃囊，赤如丹火，六足四翼，渾敦無面目，是識歌舞，實惟帝江也。','draft'),
('25000000-0000-4000-8000-000000000048','en','Dijiang',ARRAY['帝江'],'','','draft'),
('25000000-0000-4000-8000-000000000049','zh-CN','蓐收',ARRAY[]::text[],'神，见于泑山（第 59 段）。','原文：神蓐收居之。','draft'),
('25000000-0000-4000-8000-000000000049','en','Rushou',ARRAY['蓐收'],'','','draft'),
('25000000-0000-4000-8000-000000000050','zh-CN','红光',ARRAY['紅光'],'神，见于泑山（第 59 段）。','原文：神紅光之所司也','draft'),
('25000000-0000-4000-8000-000000000050','en','Hongguang',ARRAY['紅光'],'','','draft'),
('25000000-0000-4000-8000-000000000051','zh-CN','讙',ARRAY[]::text[],'兽，见于翼望之山（第 60 段）。','原文：有獸焉，其狀如狸，一目而三尾，名曰讙，其音如𡙸百聲，是可以禦凶，服之已癉。','draft'),
('25000000-0000-4000-8000-000000000051','en','Huan',ARRAY['讙'],'','','draft'),
('25000000-0000-4000-8000-000000000052','zh-CN','鵸鵌',ARRAY[]::text[],'鸟，见于翼望之山（第 60 段）。','原文：有鳥焉，其狀如烏，三首六尾而善笑，名曰鵸鵌，服之使人不厭，又可以禦凶。','draft'),
('25000000-0000-4000-8000-000000000052','en','Qitu',ARRAY['鵸鵌'],'','','draft'),
('25000000-0000-4000-8000-000000000053','zh-CN','当扈',ARRAY['當扈'],'鸟，见于上申之山（第 67 段）。','原文：其鳥多當扈，其狀如雉，以其髯飛，食之不眴目。','draft'),
('25000000-0000-4000-8000-000000000053','en','Danghu',ARRAY['當扈'],'','','draft'),
('25000000-0000-4000-8000-000000000054','zh-CN','神𩳁',ARRAY[]::text[],'神，见于刚山（第 74 段）。','原文：是多神𩳁，其狀人面獸身，一足一手，其音如欽。','draft'),
('25000000-0000-4000-8000-000000000054','en','Shenchi',ARRAY['神𩳁'],'','','draft'),
('25000000-0000-4000-8000-000000000055','zh-CN','蛮蛮',ARRAY['蠻蠻'],'兽，见于刚山之尾（第 75 段）。','原文：其中多蠻蠻，其狀鼠身而鱉首，其音如吠犬。','draft'),
('25000000-0000-4000-8000-000000000055','en','Manman',ARRAY['蠻蠻'],'','','draft'),
('25000000-0000-4000-8000-000000000056','zh-CN','冉遗之鱼',ARRAY['冉遺之魚'],'鱼，见于英鞮之山（第 76 段）。','原文：是多冉遺之魚，魚身蛇首、六足，其目如馬耳，食之使人不眯，可以禦凶。','draft'),
