('25000000-0000-4000-8000-000000000062','en','Shuhu',ARRAY['孰湖'],'','','draft')
INSERT INTO shj_creature_occurrences(id,creature_id,passage_id,place_id,surface_form,quote_zh,occurrence_order,source_attestation,interpretation_class,confidence,evidence_note,review_status) VALUES
('26000000-0000-4000-8000-000000000001','25000000-0000-4000-8000-000000000001','23000000-0000-4000-8000-000000000001','24000000-0000-4000-8000-000000000001','羬羊','有獸焉，其狀如羊而馬尾，名曰羬羊，其脂可以已腊。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000002','25000000-0000-4000-8000-000000000002','23000000-0000-4000-8000-000000000002','24000000-0000-4000-8000-000000000002','䳋渠','有鳥焉，其名曰䳋渠，其狀如山雞，黑身赤足，可以已𦢊。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000003','25000000-0000-4000-8000-000000000003','23000000-0000-4000-8000-000000000003','24000000-0000-4000-8000-000000000003','肥𧔥','有蛇焉，名曰肥𧔥，六足四翼，見則天下大旱。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000004','25000000-0000-4000-8000-000000000004','23000000-0000-4000-8000-000000000005','24000000-0000-4000-8000-000000000005','葱聾','其獸多葱聾，其狀如羊而赤鬣。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000005','25000000-0000-4000-8000-000000000005','23000000-0000-4000-8000-000000000005','24000000-0000-4000-8000-000000000005','鴖','其鳥多鴖，其狀如翠而赤喙，可以禦火。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000006','25000000-0000-4000-8000-000000000006','23000000-0000-4000-8000-000000000007','24000000-0000-4000-8000-000000000007','䰷魚','其中多䰷魚，其狀如鱉，其音如羊。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000007','25000000-0000-4000-8000-000000000007','23000000-0000-4000-8000-000000000007','24000000-0000-4000-8000-000000000007','肥遺','有鳥焉，其狀如鶉，黃身而赤喙，其名曰肥遺，食之已癘，可以殺蟲。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000008','25000000-0000-4000-8000-000000000008','23000000-0000-4000-8000-000000000008','24000000-0000-4000-8000-000000000008','人魚','其中多水玉，多人魚。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000009','25000000-0000-4000-8000-000000000009','23000000-0000-4000-8000-000000000008','24000000-0000-4000-8000-000000000008','毫彘','有獸焉，其狀如豚而白毛，大如笄而黑端，名曰毫彘。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000010','25000000-0000-4000-8000-000000000010','23000000-0000-4000-8000-000000000010','24000000-0000-4000-8000-000000000010','囂','有獸焉，其狀如禺而長臂，善投，其名曰囂。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000011','25000000-0000-4000-8000-000000000011','23000000-0000-4000-8000-000000000010','24000000-0000-4000-8000-000000000010','橐𩇯','有鳥焉，其狀如梟，人面而一足，曰橐𩇯，冬見夏蟄，服之不畏雷。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000012','25000000-0000-4000-8000-000000000012','23000000-0000-4000-8000-000000000015','24000000-0000-4000-8000-000000000015','谿邊','有獸焉，其狀如狗，名曰谿邊，席其皮者不蠱。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000013','25000000-0000-4000-8000-000000000013','23000000-0000-4000-8000-000000000015','24000000-0000-4000-8000-000000000015','櫟','有鳥焉，其狀如鶉，黑文而赤翁，名曰櫟，食之已痔。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000014','25000000-0000-4000-8000-000000000014','23000000-0000-4000-8000-000000000016','24000000-0000-4000-8000-000000000016','𤣎如','有獸焉，其狀如鹿而白尾，馬足人手而四角，名曰𤣎如。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000015','25000000-0000-4000-8000-000000000015','23000000-0000-4000-8000-000000000016','24000000-0000-4000-8000-000000000016','數斯','有鳥焉，其狀如鴟而人足，名曰數斯，食之已癭。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000016','25000000-0000-4000-8000-000000000016','23000000-0000-4000-8000-000000000017','24000000-0000-4000-8000-000000000017','𤛎','有獸焉，其狀如牛，而蒼黑大目，其名曰𤛎。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000017','25000000-0000-4000-8000-000000000017','23000000-0000-4000-8000-000000000017','24000000-0000-4000-8000-000000000017','鸚䳇','有鳥焉，其狀如鴞，青羽赤喙，人舌能言，名曰鸚䳇。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000018','25000000-0000-4000-8000-000000000018','23000000-0000-4000-8000-000000000018','24000000-0000-4000-8000-000000000018','鸓','其鳥多鸓，其狀如鵲，赤黑而兩首四足，可以禦火。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000019','25000000-0000-4000-8000-000000000019','23000000-0000-4000-8000-000000000025','24000000-0000-4000-8000-000000000024','鸞鳥','有鳥焉，其狀如翟而五彩文，名曰鸞鳥，見則天下安寧。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000020','25000000-0000-4000-8000-000000000020','23000000-0000-4000-8000-000000000027','24000000-0000-4000-8000-000000000026','鳧徯','有鳥焉，其狀如雄雞而人面，名曰鳧徯，其鳴自叫也，見則有兵。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000021','25000000-0000-4000-8000-000000000021','23000000-0000-4000-8000-000000000029','24000000-0000-4000-8000-000000000028','朱厭','有獸焉，其狀如猿，而白首赤足，名曰朱厭，見則大兵。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000022','25000000-0000-4000-8000-000000000022','23000000-0000-4000-8000-000000000037','24000000-0000-4000-8000-000000000036','羅羅','其鳥多羅羅，是食人。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000023','25000000-0000-4000-8000-000000000023','23000000-0000-4000-8000-000000000039','24000000-0000-4000-8000-000000000037','舉父','有獸焉，其狀如禺而文臂，豹虎而善投，名曰舉父。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000024','25000000-0000-4000-8000-000000000024','23000000-0000-4000-8000-000000000039','24000000-0000-4000-8000-000000000037','蠻蠻','有鳥焉，其狀如鳧，而一翼一目，相得乃飛，名曰蠻蠻，見則天下大水。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000025','25000000-0000-4000-8000-000000000025','23000000-0000-4000-8000-000000000043','24000000-0000-4000-8000-000000000041','鼓','其子曰鼓，其狀如人面而龍身，是與欽䲹殺葆江于崑崙之陽',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000026','25000000-0000-4000-8000-000000000026','23000000-0000-4000-8000-000000000043','24000000-0000-4000-8000-000000000041','欽䲹','欽䲹化為大鶚，其狀如鵰而黑文白首，赤喙而虎爪，其音如晨鵠，見則有大兵',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000027','25000000-0000-4000-8000-000000000027','23000000-0000-4000-8000-000000000044','24000000-0000-4000-8000-000000000042','文鰩魚','是多文鰩魚，狀如鯉魚，魚身而鳥翼，蒼文而白首，赤喙，常行西海，遊於東海，以夜飛。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000028','25000000-0000-4000-8000-000000000028','23000000-0000-4000-8000-000000000045','24000000-0000-4000-8000-000000000043','蠃母','其中多蠃母，其上多青雄黃',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000029','25000000-0000-4000-8000-000000000029','23000000-0000-4000-8000-000000000045','24000000-0000-4000-8000-000000000043','英招','神英招司之，其狀馬身而人面，虎文而鳥翼，徇于四海，其音如榴。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000030','25000000-0000-4000-8000-000000000030','23000000-0000-4000-8000-000000000045','24000000-0000-4000-8000-000000000043','天神','有天神焉，其狀如牛，而八足二首馬尾，其音如勃皇，見則其邑有兵。',3,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000031','25000000-0000-4000-8000-000000000031','23000000-0000-4000-8000-000000000046','24000000-0000-4000-8000-000000000044','陸吾','神陸吾司之。其神狀虎身而九尾，人面而虎爪；是神也，司天之九部及帝之囿時。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000032','25000000-0000-4000-8000-000000000032','23000000-0000-4000-8000-000000000046','24000000-0000-4000-8000-000000000044','土螻','有獸焉，其狀如羊而四角，名曰土螻，是食人。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000033','25000000-0000-4000-8000-000000000033','23000000-0000-4000-8000-000000000046','24000000-0000-4000-8000-000000000044','欽原','有鳥焉，其狀如蜂，大如鴛鴦，名曰欽原，蠚鳥獸則死，蠚木則枯。',3,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000034','25000000-0000-4000-8000-000000000034','23000000-0000-4000-8000-000000000046','24000000-0000-4000-8000-000000000044','鶉鳥','有鳥焉，其名曰鶉鳥，是司帝之百服。',4,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000035','25000000-0000-4000-8000-000000000035','23000000-0000-4000-8000-000000000047','24000000-0000-4000-8000-000000000045','滑魚','其中多滑魚，其狀如蛇而四足，是食魚。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000036','25000000-0000-4000-8000-000000000036','23000000-0000-4000-8000-000000000048','24000000-0000-4000-8000-000000000047','長乘','神長乘司之，是天之九德也。其神狀如人而犳尾。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000037','25000000-0000-4000-8000-000000000037','23000000-0000-4000-8000-000000000049','24000000-0000-4000-8000-000000000048','西王母','西王母其狀如人，豹尾虎齒而善嘯，蓬髮戴勝，是司天之厲及五殘。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000038','25000000-0000-4000-8000-000000000038','23000000-0000-4000-8000-000000000049','24000000-0000-4000-8000-000000000048','狡','有獸焉，其狀如犬而豹文，其角如牛，其名曰狡，其音如吠犬，見則其國大穰。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000039','25000000-0000-4000-8000-000000000039','23000000-0000-4000-8000-000000000049','24000000-0000-4000-8000-000000000048','胜遇','有鳥焉，其狀如翟而赤，名曰胜遇，是食魚，其音如錄，見則其國大水。',3,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000040','25000000-0000-4000-8000-000000000040','23000000-0000-4000-8000-000000000052','24000000-0000-4000-8000-000000000051','白帝少昊','其神白帝少昊居之。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000041','25000000-0000-4000-8000-000000000041','23000000-0000-4000-8000-000000000053','24000000-0000-4000-8000-000000000052','猙','有獸焉，其狀如赤豹，五尾一角，其音如擊石，其名如猙。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000042','25000000-0000-4000-8000-000000000042','23000000-0000-4000-8000-000000000053','24000000-0000-4000-8000-000000000052','畢方','有鳥焉，其狀如鶴，一足，赤文青質而白喙，名曰畢方，其鳴自叫也，見則其邑有譌火。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000043','25000000-0000-4000-8000-000000000043','23000000-0000-4000-8000-000000000054','24000000-0000-4000-8000-000000000053','天狗','有獸焉，其狀如狸而白首，名曰天狗，其音如榴榴，可以禦凶。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000044','25000000-0000-4000-8000-000000000044','23000000-0000-4000-8000-000000000056','24000000-0000-4000-8000-000000000055','三青鳥','三青鳥居之。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000045','25000000-0000-4000-8000-000000000045','23000000-0000-4000-8000-000000000056','24000000-0000-4000-8000-000000000055','𢕟𢓨','其上有獸焉，其狀如牛，白身四角，其毫如披蓑，其名曰𢕟𢓨，是食人。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000046','25000000-0000-4000-8000-000000000046','23000000-0000-4000-8000-000000000056','24000000-0000-4000-8000-000000000055','鴟','有鳥焉，一首而三身，其狀如𪇱，其名曰鴟。',3,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000047','25000000-0000-4000-8000-000000000047','23000000-0000-4000-8000-000000000057','24000000-0000-4000-8000-000000000056','耆童','神耆童居之，其音常如鍾磬。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000048','25000000-0000-4000-8000-000000000048','23000000-0000-4000-8000-000000000058','24000000-0000-4000-8000-000000000057','帝江','有神焉，其狀如黃囊，赤如丹火，六足四翼，渾敦無面目，是識歌舞，實惟帝江也。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000049','25000000-0000-4000-8000-000000000049','23000000-0000-4000-8000-000000000059','24000000-0000-4000-8000-000000000058','蓐收','神蓐收居之。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000050','25000000-0000-4000-8000-000000000050','23000000-0000-4000-8000-000000000059','24000000-0000-4000-8000-000000000058','紅光','神紅光之所司也',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000051','25000000-0000-4000-8000-000000000051','23000000-0000-4000-8000-000000000060','24000000-0000-4000-8000-000000000059','讙','有獸焉，其狀如狸，一目而三尾，名曰讙，其音如𡙸百聲，是可以禦凶，服之已癉。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000052','25000000-0000-4000-8000-000000000052','23000000-0000-4000-8000-000000000060','24000000-0000-4000-8000-000000000059','鵸鵌','有鳥焉，其狀如烏，三首六尾而善笑，名曰鵸鵌，服之使人不厭，又可以禦凶。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000053','25000000-0000-4000-8000-000000000053','23000000-0000-4000-8000-000000000067','24000000-0000-4000-8000-000000000065','當扈','其鳥多當扈，其狀如雉，以其髯飛，食之不眴目。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000054','25000000-0000-4000-8000-000000000054','23000000-0000-4000-8000-000000000074','24000000-0000-4000-8000-000000000072','神𩳁','是多神𩳁，其狀人面獸身，一足一手，其音如欽。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000055','25000000-0000-4000-8000-000000000055','23000000-0000-4000-8000-000000000075','24000000-0000-4000-8000-000000000073','蠻蠻','其中多蠻蠻，其狀鼠身而鱉首，其音如吠犬。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000056','25000000-0000-4000-8000-000000000056','23000000-0000-4000-8000-000000000076','24000000-0000-4000-8000-000000000074','冉遺之魚','是多冉遺之魚，魚身蛇首、六足，其目如馬耳，食之使人不眯，可以禦凶。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000057','25000000-0000-4000-8000-000000000057','23000000-0000-4000-8000-000000000077','24000000-0000-4000-8000-000000000075','駮','有獸焉，其狀如馬而白身黑尾，一角，虎牙爪，音如鼓音，其名曰駮，是食虎豹，可以禦兵。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000058','25000000-0000-4000-8000-000000000058','23000000-0000-4000-8000-000000000078','24000000-0000-4000-8000-000000000076','窮奇','其上有獸焉，其狀如牛，蝟毛，名曰窮奇，音如獋狗，是食人。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000059','25000000-0000-4000-8000-000000000059','23000000-0000-4000-8000-000000000078','24000000-0000-4000-8000-000000000076','蠃魚','蠃魚，魚身而鳥翼，音如鴛鴦，見則其邑大水。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000060','25000000-0000-4000-8000-000000000060','23000000-0000-4000-8000-000000000079','24000000-0000-4000-8000-000000000077','鰠魚','其中多鰠魚，其狀如鱣魚，動則其邑有大兵。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000061','25000000-0000-4000-8000-000000000061','23000000-0000-4000-8000-000000000079','24000000-0000-4000-8000-000000000077','𩶯魮之魚','多𩶯魮之魚，其狀如覆銚，鳥首而魚翼魚尾，音如磬石之聲，是生珠玉。',2,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000000062','25000000-0000-4000-8000-000000000062','23000000-0000-4000-8000-000000000080','24000000-0000-4000-8000-000000000078','孰湖','有獸焉，其狀馬身而鳥翼，人面蛇尾，是好舉人，名曰孰湖。',1,'text_direct','transcription','high','首见；引文为该段连续子串，由生成器断言。','draft'),
('26000000-0000-4000-8000-000000001000','25000000-0000-4000-8000-000000000025','23000000-0000-4000-8000-000000000043','24000000-0000-4000-8000-000000000041','鵔鳥','鼓亦化為鵔鳥，其狀如鴟，赤足而直喙，黃文而白首，其音如鵠，見則其邑大旱。',3,'text_direct','transcription','high','鼓被戮之后化为鵔鸟，同一概念的化身形态','draft'),
('26000000-0000-4000-8000-000000001001','25000000-0000-4000-8000-000000000026','23000000-0000-4000-8000-000000000043','24000000-0000-4000-8000-000000000041','欽䲹','是與欽䲹殺葆江于崑崙之陽',4,'text_direct','transcription','high','欽䲹与鼓共杀葆江，此为其化身之前的记载','draft')
