('29000000-0000-4000-8000-000000000003','23000000-0000-4000-8000-000000000061',NULL,'6744里','unresolved','本列段内里程相加为 6640 里，与结语所称 6744 里差 -104 里；依政策 §4.5.3a，数字差异不以弥合结语为定案标准，登记不裁决。','xishan-li-not-reconciled','R-AI-EXTRACT',DATE '2026-08-19'),
('29000000-0000-4000-8000-000000000004','23000000-0000-4000-8000-000000000081',NULL,'3680里','unresolved','本列段内里程相加为 3585 里，与结语所称 3680 里差 -95 里；依政策 §4.5.3a，数字差异不以弥合结语为定案标准，登记不裁决。','xishan-li-not-reconciled','R-AI-EXTRACT',DATE '2026-08-19'),
('29000000-0000-4000-8000-000000000010','23000000-0000-4000-8000-000000000082',NULL,'17517里','unresolved','四列结语里程相加为 17521 里，全篇结语作 17517 里，差 4 里；段内相加为 17712 里。三个数字互不相合。','xishan-li-not-reconciled','R-AI-EXTRACT',DATE '2026-08-19')
INSERT INTO shj_editorial_decisions(id,work_id,decision_key,decision_type,subject_kind,subject_ref,decision_status,rationale,evidence_note,reviewer_role,decided_at) VALUES
('2a000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000011','xishan-station-vs-mountain-count','topology','topology','xishan-full-v1','accepted','四列结语山数相加为 78，全篇结语作 77，差 1。差在西次三经：该列结语称 23 山，而本列共 23 站——第 48 段一段两站（「西水行四百里，曰流沙，二百里至于蠃母之山」）。流沙非山，故 78 是站数、77 是山数。两个数各自都对，计量单位不同而已，不是讹误。','逐段解析得 78 站、77 山；四列站数 19/17/23/19 与各自结语 19/17/23/19 逐条吻合。','R-AI-EXTRACT',DATE '2026-08-19'),
('2a000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000011','xishan-li-not-reconciled','variant','passage','xishan-full-v1','provisional','里程三个口径互不相合：段内相加 17712、四列结语相加 17521、全篇结语 17517。依政策 §4.5.3a，数字差异不高于 provisional，本轮只登记不裁决。','第1列 2817/2957（差 -140）；第2列 4670/4140（差 530）；第3列 6640/6744（差 -104）；第4列 3585/3680（差 -95）','R-AI-EXTRACT',DATE '2026-08-19'),
('2a000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000011','xishan-water-elision-merge','merge','place','xishan-waters','accepted','「渭」「河」「洛」与「渭水」「河水」「洛水」在本篇并见，省称与全称指同一水，合为一个地点。','合并 渭→渭水、河→河水、洛→洛水；两种写法都保留为别名。','R-AI-EXTRACT',DATE '2026-08-19'),
('2a000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000011','xishan-place-slug-prefix','canonical_name','place','xishan-places','accepted','《西山经》地点 slug 一律加 xi- 前缀。路线站点本就属于篇目；且裸拼音与已入库的《南山经》地点相撞（符禺之山与浮玉之山同作 fuyu）。','143 个地点，无一与既有 slug 冲突。','R-AI-EXTRACT',DATE '2026-08-19'),
('2a000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000011','xishan-general-taxonomy-terms','canonical_name','taxonomy','xishan-taxonomy','accepted','本篇的分类词条取通用类目（人面、多首多足、有角、疗疾之效…），不为每只异兽单立一词。一兽一词不是分类，是把描述换个写法重说一遍；62 个概念足以让这个反模式显形。','125 条指派落在 36 个词条上，平均每词 3.5 次。《南山经》既有的逐兽词条留待日后统一，不在本轮改动。','R-AI-EXTRACT',DATE '2026-08-19'),
('2a000000-0000-4000-8000-000000000006','10000000-0000-4000-8000-000000000011','xishan-deities-as-creatures','canonical_name','creature','xishan-deities','accepted','神祇（西王母、陆吾、帝江、蓐收等）与异兽同表，另设 being_kind 轴区分。《西山经》去掉神祇便所剩无几，另立一表则要在证据链上重复一整套结构。','13 个概念记为 deity。','R-AI-EXTRACT',DATE '2026-08-19'),
('2a000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000011','xishan-unnamed-beings-deferred','occurrence','occurrence','xishan-deferred','provisional','原文未出其名者不代拟名。五处存疑登记为待裁候选，不建概念。','第43段 葆江；第45段 槐鬼離侖；第45段 窮鬼；第52段 員神磈氏；第80段 （无名之鸟）','R-AI-EXTRACT',DATE '2026-08-19'),
('2a000000-0000-4000-8000-000000000008','10000000-0000-4000-8000-000000000011','xishan-transliteration-not-translation','canonical_name','place','xishan-bilingual','accepted','英文只给专名转写，不给译文摘要。转写依 scripts/data/xishan_readings_v1.json 逐字可复核；译一段古文不可，那要人负责（执行清单 1-2）。','用字表 271 字，其中 14 字读音存疑，已在评审单单列。','R-AI-EXTRACT',DATE '2026-08-19')
