('2b000000-0000-4000-8000-000000000003','23000000-0000-4000-8000-000000000045','窮鬼',NULL,NULL,'pending_review',NULL,NULL,'见于「東望恒山四成」的远望之辞，非本山所有','R-AI-EXTRACT',DATE '2026-08-19'),
